import{_ as t,c as a,o as n,j as s,Y as r,t as i}from"./chunks/framework.D-NV0Bun.js";const u=JSON.parse('{"title":"docker-network-rm | x-cmd man (docker man1) | Remove one or more networks","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker-network-rm - Remove one or more networks","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker-network-rm | x-cmd man (docker man1) | Remove one or more networks"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker-network-rm - Remove one or more networks"}]]},"headers":[],"params":{"isMan":true,"man":"docker-network-rm","category":"docker man1","desc":"Remove one or more networks"},"relativePath":"docker/man1/docker-network-rm.md","filePath":"docker/man1/[man].md"}'),d={name:"docker/man1/docker-network-rm.md"},l={class:"visually-hidden"};function k(o,e,h,m,c,p){return n(),a("div",null,[s("h1",l,i(o.$params.man),1),e[0]||(e[0]=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker-network-rm - Remove one or more networks</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker network rm NETWORK [NETWORK...]</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Removes one or more networks by name or identifier. To remove a network, you must first disconnect any containers connected to it. To remove the network named &#39;my-network&#39;:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-network</span></span></code></pre></div><p>To delete multiple networks in a single <strong>docker network rm</strong> command, provide multiple network names or ids. The following example deletes a network with id <strong>3695c422697f</strong> and a network named <strong>my-network</strong>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3695c422697f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-network</span></span></code></pre></div><p>When you specify multiple networks, the command attempts to delete each in turn. If the deletion of one network fails, the command continues to the next on the list and tries to delete that. The command reports success or failure for each deletion.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>-f</strong>, <strong>--force</strong>[=false] Do not error if the network does not exist</p><p><strong>-h</strong>, <strong>--help</strong>[=false] help for rm</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>docker-network(1)</strong></p>',15))])}c